package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type SalesRec struct {
	SrId    string
	SrSales decimal.Decimal
}

type TierTable struct {
	TierEntry struct {
		TierLimit decimal.Decimal
		TierRate  decimal.Decimal
	}
}

var WsEofFlag string = "N"
var WsIdx int64 = 0
var WsTier int64 = 0
var WsComm decimal.Decimal = decimal.New(0, 0)
var WsTotal decimal.Decimal = decimal.New(0, 0)
var WsCount int64 = 0
var WsSalesEd string
var WsRateEd string
var WsCommEd string
var WsTotalEd string

var tierLimits [5]decimal.Decimal
var tierRates [5]decimal.Decimal

var salesRec SalesRec

var inputLines []string
var inputPos int

func isInputDone() bool {
	return WsEofFlag == "Y"
}
func setInputDone() {
	WsEofFlag = "Y"
}

func fitDec(v decimal.Decimal, intDigits int, fracDigits int) decimal.Decimal {
	modPow := intDigits + fracDigits
	mod := decimal.New(1, int32(modPow))
	scaled := v.Shift(int32(fracDigits)).Truncate(0)
	// positive modulo for low-order digits
	q := scaled.Div(mod).Truncate(0)
	r := scaled.Sub(q.Mul(mod))
	return r.Shift(int32(-fracDigits))
}

func fitInt(v int64, digits int) int64 {
	if digits <= 0 {
		return 0
	}
	m := int64(1)
	for i := 0; i < digits; i++ {
		m *= 10
	}
	r := v % m
	if r < 0 {
		r += m
	}
	return r
}

func parsePic9V99(s string) decimal.Decimal {
	var n int64 = 0
	for i := 0; i < len(s); i++ {
		c := s[i]
		var d int64 = 0
		if c >= '0' && c <= '9' {
			d = int64(c - '0')
		} else if c == ' ' {
			d = 0
		} else if c == 0 {
			d = 0
		} else {
			d = 0
		}
		n = n*10 + d
	}
	return decimal.New(n, -2)
}

func padRight(s string, n int) string {
	if len(s) >= n {
		return s[:n]
	}
	return s + strings.Repeat(" ", n-len(s))
}

// format Z-edited with given integer pattern (e.g. "ZZZ,ZZ9") and 2 frac digits
func formatZEdited(v decimal.Decimal, intPattern string, fracDigits int) string {
	// count integer digits
	intWidth := 0
	for i := 0; i < len(intPattern); i++ {
		if intPattern[i] == 'Z' || intPattern[i] == '9' {
			intWidth++
		}
	}
	// get digits (low-order truncation already done, but ensure)
	// work with absolute value; inputs are non-negative
	neg := v.IsNegative()
	av := v
	if neg {
		av = v.Neg()
	}
	// ensure scale
	// get scaled integer
	scaled := av.Shift(int32(fracDigits)).Round(0)
	fracMod := int64(1)
	for i := 0; i < fracDigits; i++ {
		fracMod *= 10
	}
	intPartScaled := scaled.Div(decimal.New(fracMod, 0)).Truncate(0)
	fracPartScaled := scaled.Sub(intPartScaled.Mul(decimal.New(fracMod, 0)))
	intNum := intPartScaled.IntPart()
	fracNum := fracPartScaled.IntPart()
	if intNum < 0 {
		intNum = -intNum
	}
	if fracNum < 0 {
		fracNum = -fracNum
	}
	// keep low-order intWidth digits
	mod := int64(1)
	for i := 0; i < intWidth; i++ {
		mod *= 10
	}
	intNum = intNum % mod
	if intNum < 0 {
		intNum += mod
	}
	// digits string zero padded
	digits := fmt.Sprintf("%0*d", intWidth, intNum)
	fracStr := fmt.Sprintf("%0*d", fracDigits, fracNum)
	// find first nonzero
	k := intWidth - 1
	for i := 0; i < intWidth; i++ {
		if digits[i] != '0' {
			k = i
			break
		}
	}
	// if all zero, k stays last
	allZero := true
	for i := 0; i < intWidth; i++ {
		if digits[i] != '0' {
			allZero = false
			break
		}
	}
	if allZero {
		k = intWidth - 1
	}
	var b strings.Builder
	di := 0
	for pi := 0; pi < len(intPattern); pi++ {
		ch := intPattern[pi]
		if ch == ',' {
			// left digit index = di-1
			leftIdx := di - 1
			if leftIdx < k {
				b.WriteByte(' ')
			} else {
				b.WriteByte(',')
			}
		} else {
			d := digits[di]
			if di < k {
				b.WriteByte(' ')
			} else {
				b.WriteByte(d)
			}
			di++
		}
	}
	b.WriteByte('.')
	b.WriteString(fracStr)
	return b.String()
}

func formatRate(v decimal.Decimal) string {
	// PIC 9.99 : 1 int digit, 2 frac
	av := v
	if av.IsNegative() {
		av = av.Neg()
	}
	scaled := av.Shift(2).Round(0)
	fracMod := int64(100)
	intPart := scaled.Div(decimal.New(fracMod, 0)).Truncate(0).IntPart()
	fracPart := scaled.Sub(decimal.New(intPart, 0).Mul(decimal.New(fracMod, 0))).IntPart()
	if intPart < 0 {
		intPart = -intPart
	}
	if fracPart < 0 {
		fracPart = -fracPart
	}
	intPart = fitInt(intPart, 1)
	fracPart = fitInt(fracPart, 2)
	return fmt.Sprintf("%d.%02d", intPart, fracPart)
}

func formatCount(v int64) string {
	v = fitInt(v, 3)
	if v < 0 {
		v += 1000
	}
	return fmt.Sprintf("%03d", v)
}

func formatTier(v int64) string {
	v = fitInt(v, 1)
	return fmt.Sprintf("%d", v)
}

func INITPARA() {
	tierLimits[1] = decimal.New(100000, -2)
	tierRates[1] = decimal.New(250, -2)
	tierLimits[2] = decimal.New(500000, -2)
	tierRates[2] = decimal.New(400, -2)
	tierLimits[3] = decimal.New(2000000, -2)
	tierRates[3] = decimal.New(550, -2)
	tierLimits[4] = decimal.New(99999999, -2)
	tierRates[4] = decimal.New(725, -2)
}

func READPARA() {
	if inputPos >= len(inputLines) {
		setInputDone()
		return
	}
	line := inputLines[inputPos]
	inputPos++
	rec := padRight(line, 12)
	srId := rec[0:4]
	srSalesStr := rec[4:12]
	salesRec.SrId = srId
	salesRec.SrSales = parsePic9V99(srSalesStr)
}

func PROCESSPARA() {
	WsTier = fitInt(0, 1)
	WsIdx = 1
	for !(WsIdx > 4 || WsTier > 0) {
		if salesRec.SrSales.Cmp(tierLimits[WsIdx]) <= 0 {
			WsTier = fitInt(WsIdx, 1)
		}
		WsIdx++
	}
	WsIdx = fitInt(WsIdx, 1)
	tier := WsTier
	if tier < 1 || tier > 4 {
		tier = 4
		WsTier = 4
	}
	prod := salesRec.SrSales.Mul(tierRates[tier])
	comp := prod.Shift(-2).Round(2)
	WsComm = fitDec(comp, 6, 2)
	WsTotal = fitDec(WsTotal.Add(WsComm), 9, 2)
	WsCount = fitInt(WsCount+1, 3)
	WsSalesEd = formatZEdited(salesRec.SrSales, "ZZZ,ZZ9", 2)
	WsRateEd = formatRate(tierRates[tier])
	WsCommEd = formatZEdited(WsComm, "ZZZ,ZZ9", 2)
	fmt.Fprintln(os.Stdout, salesRec.SrId+" T"+formatTier(WsTier)+" "+WsSalesEd+" "+WsRateEd+"% "+WsCommEd)
	READPARA()
}

func SUMMARYPARA() {
	WsTotalEd = formatZEdited(WsTotal, "ZZZ,ZZZ,ZZ9", 2)
	fmt.Fprintln(os.Stdout, "REPS: "+formatCount(WsCount)+" TOTAL: "+WsTotalEd)
}

func main() {
	INITPARA()
	f, err := os.Open("input.dat")
	if err != nil {
		if os.IsNotExist(err) {
			inputLines = []string{}
		} else {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
	} else {
		sc := bufio.NewScanner(f)
		// allow long lines
		sc.Buffer(make([]byte, 1024*1024), 1024*1024)
		for sc.Scan() {
			s := sc.Text()
			if len(s) > 0 && s[len(s)-1] == '\r' {
				s = s[:len(s)-1]
			}
			inputLines = append(inputLines, s)
		}
		f.Close()
		if err := sc.Err(); err != nil {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
	}
	inputPos = 0
	READPARA()
	for !isInputDone() {
		PROCESSPARA()
	}
	SUMMARYPARA()
}
